VALUES
        ('cc7c13ca-22d1-516b-a624-f7343af330fd'::uuid, '0a55e172-f320-4319-83fb-5152091b00f5'::uuid, 'Yeşil dönüşümde kritik mineral olarak metinde hangi örnek verilmektedir?', 1, 1, 3, 'Lityum, batarya teknolojilerinde kullanılan ve yeşil dönüşüm için stratejik görülen minerallerden biridir.', 'Lityum', 'Kömür', 'Petrol', 'Doğalgaz', 'A', 4),
        ('4fdc0f89-0d82-5508-aec2-51cb88cae7b5'::uuid, '0a55e172-f320-4319-83fb-5152091b00f5'::uuid, 'Güneş ve rüzgâr kaynaklarının yerel olarak üretilebilmesi hangi jeopolitik olanağı güçlendirir?', 2, 2, 3, 'Yerel yenilenebilir üretim, ülkelerin enerji ihtiyacını dış tedarikçilere daha az bağlı karşılamasına yardımcı olabilir.', 'Yakıt ithalatını artırmayı', 'Dış enerji bağımlılığını azaltmayı', 'Petrol gelirlerini yükseltmeyi', 'Kritik maden işleme tekelini korumayı', 'B', 5),
        ('4907177d-b9d2-5aa1-b4cb-8cdf35ced021'::uuid, '0a55e172-f320-4319-83fb-5152091b00f5'::uuid, 'Bir ülkenin güneş enerjisi kaynağına sahip olup yine de teknoloji bağımlısı kalması nasıl açıklanır?', 2, 2, 3, 'Kaynak ülke içinde bulunsa bile panel, batarya ve kontrol yazılımlarının dışarıdan alınması yeni bir bağımlılık yaratabilir.', 'Güneş ışığının yalnızca dışarıdan satın alınabilmesiyle', 'Yenilenebilir elektriğin depolanamamasıyla', 'Panel, batarya ve yazılımı dışarıdan almasıyla', 'Petrol kuyularının yenilenebilir santrallere dönüşmesiyle', 'C', 6),
        ('9f051b71-0d2e-55a1-a483-62254be55961'::uuid, '0a55e172-f320-4319-83fb-5152091b00f5'::uuid, 'Rantiyer devletlerin fosil yakıt talebi azalırken karşılaşabileceği temel risk nedir?', 2, 2, 3, 'Bütçesi büyük ölçüde fosil yakıt ihracatına dayanan devletler, talep ve fiyat düştüğünde gelir kaynaklarını kaybetme riski taşır.', 'İhracat gelirlerinin bütçeyi artık desteklememesi', 'Yenilenebilir kaynakların bir anda tükenmesi', 'Kritik madenlerin bütün ülkelerde bitmesi', 'Enerji verimliliğinin otomatik olarak düşmesi', 'D', 7),
        ('adfced91-ca2a-5d9f-a113-009785353a4b'::uuid, '0a55e172-f320-4319-83fb-5152091b00f5'::uuid, 'Yeşil paradoks hangi etik sorunu görünür kılar?', 3, 3, 3, 'Elektrikli araç veya batarya üretimi emisyonu azaltırken maden çıkarma yükünü kırılgan topluluklara taşıyabilir; bu nedenle geçişin adil olması gerekir.', 'Emisyonu azaltan ürünlerin maden çıkarma yükünü başka topluluklara taşıyabilmesini', 'Yenilenebilir enerjinin her koşulda ücretsiz olmasını', 'Geri dönüşümün hiçbir yeni kaynak gerektirmemesini', 'Elektrikli araçların çevresel etkilerinin yalnızca egzoz salımıyla sınırlı sanılması', 'A', 8),
        ('542fb92b-98ac-51be-98b1-075d15350de9'::uuid, '10a7e06b-84a9-4df0-a3e7-051a561d818a'::uuid, 'Siborglaşma tartışmasının merkezindeki değişim aşağıdakilerden hangisidir?', 1, 1, 3, 'Siborglaşma, insan yetilerinin beyin-makine arayüzleri veya başka teknolojilerle desteklenmesi ihtimalini tartışır.', 'İnsan bedeninin ve zihninin yalnızca biyolojik kabul edilmesi', 'Teknolojinin insan davranışını hiç etkilememesi', 'Biyolojinin bütün toplumsal sorunları çözmesi', 'İnsan yetilerinin makine ve biyoteknolojiyle desteklenmesi', 'D', 4),
        ('5736c2eb-6287-529d-bd73-bb72167f7ba7'::uuid, '10a7e06b-84a9-4df0-a3e7-051a561d818a'::uuid, 'CRISPR ile tasarım bebekler tartışmasının başlıca toplumsal kaygısı nedir?', 2, 2, 3, 'Pahalı genetik geliştirmelere yalnızca bazı gruplar erişirse mevcut eşitsizlikler biyolojik bir sınıf ayrımına dönüşebilir.', 'Erişim farklarının biyolojik sınıflar yaratabilmesi', 'Her genetik müdahalenin hemen reddedilmesi', 'Teknolojinin bütün hastalıkları aynı anda iyileştirmesi', 'Ebeveynlerin çocuklarının eğitimini bırakması', 'A', 5),
        ('28861d52-9dd2-51f9-b639-312de7b2f8d8'::uuid, '10a7e06b-84a9-4df0-a3e7-051a561d818a'::uuid, 'Radikal yaşam uzatmanın metinde işaret edilen sonuçlarından biri hangisidir?', 2, 2, 3, 'Çok uzun yaşam, nüfusun sürdürülebilirliği ve kuşaklar arası kaynak paylaşımı gibi soruları yeniden gündeme getirir.', 'Yaşlanmanın bütün etik ve toplumsal sorunları kendiliğinden bitirmesi', 'Nüfus, kaynak paylaşımı ve kuşak ilişkilerinin yeniden düşünülmesi', 'Ölümün toplumdaki bütün anlamlarını kaybetmesi', 'Biyolojik bedenin teknolojiden tamamen kopması', 'B', 6),
        ('6486afc1-d0af-52af-893a-bb274b7e5265'::uuid, '10a7e06b-84a9-4df0-a3e7-051a561d818a'::uuid, 'Post-hümanizmi transhümanizmden ayıran genişletici vurgu nedir?', 3, 3, 3, 'Post-hümanizm yalnızca insanı güçlendirmeyi değil, insan dışı varlıklarla ve ekosistemlerle ilişkimizin ahlaki çerçevesini de sorgular.', 'Yalnızca insan performansını artırmaya odaklanması', 'Teknolojik gelişmeyi bütünüyle durdurmayı önermesi', 'İnsan dışı varlıkların ve ekolojik ilişkilerin etik alana katılması', 'Biyolojik araştırmaları yalnızca insan bedeninin tedavi amaçlarıyla sınırlı tutması', 'C', 7),
        ('95202ff1-8ab9-5a3a-9223-b3a434f758ac'::uuid, '10a7e06b-84a9-4df0-a3e7-051a561d818a'::uuid, 'Yapay zekâ tekilliği fikri insanlık açısından hangi kararı gündeme getirir?', 3, 3, 3, 'Tekillik senaryoları, çok güçlü sistemler ortaya çıktığında yönetişim ve insanın uyum sağlama biçiminin nasıl belirleneceğini gündeme taşır.', 'Bilgisayarları tümüyle kapatmayı', 'Teknolojik ilerlemeyi insan kararlarını tamamen dışlayacak biçimde hızlandırmayı', 'İnsan yaratıcılığını gereksiz saymayı', 'Gücü kimlerin yöneteceğini ve insanın nasıl uyum sağlayacağını', 'D', 8),
        ('4e8d3934-3b13-58a4-a09c-9cc7a356c683'::uuid, '1a1b0ff5-d552-40b1-80a2-66d9fd9382a1'::uuid, 'Milgram deneyi sosyal psikolojide öncelikle hangi davranışı incelemiştir?', 1, 1, 2, 'Milgram''ın çalışması, katılımcıların otorite talimatı karşısında ne ölçüde itaat ettiğini incelemiştir.', 'Yaratıcı problem çözme becerisini', 'Gruplar arası dostluğu', 'Kendiliğinden yardım etmeyi', 'Otorite talimatına itaat etmeyi', 'D', 4),
        ('510aef8c-e35d-5816-a09b-8ae8665255ec'::uuid, '1a1b0ff5-d552-40b1-80a2-66d9fd9382a1'::uuid, 'Seyirci etkisi hangi durumda yardım etme olasılığının azalmasını açıklar?', 1, 1, 2, 'Tanık sayısı arttığında sorumluluk dağıldığı için her birey yardım etme görevini başkasının üstleneceğini düşünebilir.', 'Çevrede çok sayıda tanık olduğunda', 'Olayı yalnızca kişi gördüğünde', 'Yardım görevi açıkça paylaşıldığında', 'Kişiler birbirini uzun süredir tanıdığında', 'A', 5),
        ('68518ef3-b274-5842-8898-e66a00c4dfb2'::uuid, '1a1b0ff5-d552-40b1-80a2-66d9fd9382a1'::uuid, 'Sosyal kimlik kuramına göre insanlar grup üyeliğini nasıl kullanır?', 2, 2, 2, 'Sosyal kimlik, kişinin kendisini ait olduğu grupların özellikleri ve değerleri üzerinden tanımlamasına katkı sağlar.', 'Kişisel özelliklerini tümüyle yok sayarak', 'Kendini ait olduğu grubun özellikleriyle tanımlayarak', 'Her grubu aynı değerde ve farksız görerek', 'Grup sınırlarını yalnızca biyolojik farklılıklarla açıklayarak', 'B', 6),
        ('1e9e4c10-8c94-5704-880a-a78079e34ec4'::uuid, '1a1b0ff5-d552-40b1-80a2-66d9fd9382a1'::uuid, 'Grup düşüncesinin en belirgin sakıncası aşağıdakilerden hangisidir?', 2, 2, 2, 'Grup düşüncesinde uyum sağlama baskısı, alternatifleri ve riskleri sorgulayan eleştirel sesleri susturabilir.', 'Kararların daha fazla seçenek içermesi', 'Azınlık görüşlerini dikkatle dinleyip bütün seçenekleri tartışması', 'Uyum baskısının eleştirel değerlendirmeyi bastırması', 'Her üyenin sorumluluğu açıkça üstlenmesi', 'C', 7),
        ('f8138610-e012-5ebd-9817-4c9e2dcc0c7c'::uuid, '1a1b0ff5-d552-40b1-80a2-66d9fd9382a1'::uuid, 'Bir ekip sosyal baskıyı azaltmak için hangi uygulamayı benimsemelidir?', 3, 3, 2, 'Muhalif görüşlerin güvenli biçimde ifade edilmesi, grup baskısının görünür olmasını ve daha dengeli kararlar alınmasını sağlar.', 'Tek bir kişinin bütün kararları vermesini', 'Muhalif görüşleri toplantı içinde açıkça dinlemeyi reddetmesini', 'İlk öneriyi tartışmadan uygulamasını', 'Farklı görüşleri güvenli biçimde dile getirmeyi', 'D', 8),
        ('3d41c268-4e29-5ce0-9afe-0ff878ead521'::uuid, '4e1a1036-454e-4b89-87ef-30239c429e18'::uuid, 'Evrenin enerji yoğunluğu içinde karanlık maddenin yaklaşık payı nedir?', 1, 1, 3, 'Standart kozmolojik modele göre karanlık madde yaklaşık yüzde 27''lik bir paya sahiptir; görünür madde yaklaşık yüzde 5''tir.', 'Yüzde 5', 'Yüzde 10', 'Yüzde 68', 'Yüzde 27', 'D', 4),
        ('0b9151d4-3e9b-5c8c-a360-e7c59e8c15fc'::uuid, '4e1a1036-454e-4b89-87ef-30239c429e18'::uuid, 'Gökadaların dönme hızları karanlık madde için nasıl kanıt sağlar?', 2, 2, 3, 'Gökadaların dış bölgelerindeki hızlar, yalnızca görünen madde hesaba katıldığında beklenenden yüksek kalır; bu ek kütleçekim karanlık maddeyle açıklanır.', 'Görünen maddeye ek bir kütleçekim etkisine işaret eder', 'Gökadaların hiç kütleçekimi olmadığını gösterir', 'Yıldızların yalnızca ışıkla hareket ettiğini kesin olarak kanıtlar', 'Evrenin her yönde aynı hızla çöktüğünü ortaya koyar', 'A', 5),
        ('85b11d79-f5f3-5f41-80ba-a8ed4e9e0f07'::uuid, '4e1a1036-454e-4b89-87ef-30239c429e18'::uuid, 'Karanlık enerjinin standart modeldeki yaklaşık payı hangisidir?', 1, 1, 3, 'Karanlık enerji, standart modelde evrenin enerji yoğunluğunun yaklaşık yüzde 68''ini oluşturur.', 'Yüzde 5', 'Yüzde 68', 'Yüzde 27', 'Yüzde 95', 'B', 6),
        ('040b6848-ba9a-59e8-9c0f-846a7fab930a'::uuid, '4e1a1036-454e-4b89-87ef-30239c429e18'::uuid, 'Büyük Çöküş senaryosu Büyük Donma''dan hangi yönüyle ayrılır?', 2, 2, 3, 'Büyük Çöküş, genişlemenin durarak kütleçekim etkisiyle evrenin yeniden büzülmesini öngörür; Büyük Donma ise genişlemenin sürmesidir.', 'Yıldız oluşumunun sonsuza dek hızlanmasıyla', 'Evrenin ışık hızından daha yavaş genişlemesiyle', 'Genişlemenin durup evrenin yeniden büzülmesiyle', 'Karanlık maddenin tamamen görünür hale gelmesiyle', 'C', 7),
        ('b320aa9d-dcb7-5a16-a714-396a32b1a4c2'::uuid, '4e1a1036-454e-4b89-87ef-30239c429e18'::uuid, 'Karanlık maddenin doğrudan görünmemesinin temel nedeni nedir?', 3, 3, 3, 'Karanlık madde ışığı yaymadığı, soğurmadığı veya güçlü biçimde saçmadığı için doğrudan gözlenmez; etkisi kütleçekimle anlaşılır.', 'Hiçbir kütleye sahip olmaması', 'Yalnızca Dünya''nın içinde bulunması', 'Gökadalardan çok daha hızlı hareket ettiği için görünmemesi', 'Elektromanyetik ışıkla belirgin biçimde etkileşmemesi', 'D', 8),
        ('de444e1c-c672-5132-8eb1-c26b7491abfb'::uuid, '50f26b0f-0ace-4c42-9701-a643161acf2e'::uuid, 'Dönüşümcü liderliği işlemsel liderlikten ayıran temel özellik nedir?', 1, 1, 2, 'Dönüşümcü lider, yalnızca işi ve ödülü yönetmek yerine ortak bir vizyon kurarak insanların gelişimini destekler.', 'Yalnızca görev tamamlandığında çalışana maddi ödül vermeyi', 'Kararları çalışanlardan tamamen saklaması', 'Performansı yalnızca para ile ölçmesi', 'Ortak bir vizyon ve gelişim duygusu oluşturması', 'D', 4),
        ('6ce0ceab-df48-5add-a952-9f09e351c8dd'::uuid, '50f26b0f-0ace-4c42-9701-a643161acf2e'::uuid, 'Psikolojik güvenliği yüksek bir ekipte hangi davranış beklenir?', 2, 2, 2, 'Psikolojik güvenlik, ekip üyelerinin hata, soru ve farklı görüşlerini küçük düşürülme korkusu olmadan dile getirebilmesidir.', 'Hataları ve kaygıları cezalandırılma korkusu olmadan paylaşmak', 'Sorunları yöneticiden gizlemek', 'Sadece yöneticinin konuşmasına izin vermek', 'Eleştiriyi ekip içinde kişisel ve yıkıcı bir saldırı olarak görmeyi', 'A', 5),
        ('9c3cafc0-9e92-585d-96a5-062097a0fdcd'::uuid, '50f26b0f-0ace-4c42-9701-a643161acf2e'::uuid, 'Hizmetkâr liderlik yaklaşımının önceliği nedir?', 1, 1, 2, 'Hizmetkâr liderlik, liderin gücünü kendi statüsü için değil, ekibin ihtiyaçlarını karşılamak ve gelişimini sağlamak için kullanır.', 'Liderin kendi görünürlüğünü ve kurumsal statüsünü sürekli artırmak', 'Ekibin ihtiyaçlarını ve gelişimini desteklemek', 'Kuralları her koşulda katılaştırmak', 'Bilgiyi yalnızca üst yönetimde tutmak', 'B', 6),
        ('797ea2f9-a237-56f8-a01b-bde9d73c125a'::uuid, '50f26b0f-0ace-4c42-9701-a643161acf2e'::uuid, 'Karanlık üçlü özellikleri güçlü bir yöneticide hangi risk daha olasıdır?', 2, 2, 2, 'Narsisizm, Makyavelizm ve psikopati özellikleri manipülasyon, empati eksikliği ve tükenmişlik riskini artırabilir.', 'Şeffaf geri bildirim ve güvenin artması', 'Çalışanların özerkliğinin düzenli biçimde güçlenmesi', 'Manipülasyon ve korkuya dayalı toksik bir kültür', 'Hataları güvenli öğrenme fırsatı olarak ele almayı', 'C', 7),
        ('5862d781-ce33-5707-8d3f-f3d64599c819'::uuid, '50f26b0f-0ace-4c42-9701-a643161acf2e'::uuid, 'Metnin ayrımına göre yönetim ve liderlik arasındaki ilişki nasıl özetlenebilir?', 3, 3, 2, 'Yönetim süreç ve düzeni korur; liderlik ise insanları ortak bir yön, anlam ve değişim etrafında harekete geçirir.', 'İkisi de aynı beceridir ve birbirinin yerine geçer', 'Yönetim yalnızca motivasyon, liderlik yalnızca bütçedir', 'Liderlik kuralları kaldırır, yönetim insanları yok sayar', 'Yönetim düzeni sürdürürken liderlik yön ve anlam verir', 'D', 8),
        ('3a288cdb-5dab-5b18-ac5e-d0aefc650a8f'::uuid, '623c28bb-c9cf-4ae7-8c18-e9400c35e66b'::uuid, 'Kelebek etkisi ifadesi hangi fikri özetler?', 1, 1, 3, 'Kelebek etkisi, başlangıç koşullarındaki küçük farklılıkların doğrusal olmayan süreçlerde zamanla büyük ayrışmalara yol açabilmesini anlatır.', 'Büyük sonuçların yalnızca büyük ve görünür temel nedenlerden doğması', 'Başlangıçtaki küçük farklar zamanla büyük sonuçlara dönüşebilir', 'Doğadaki bütün sistemler tamamen rastlantısaldır', 'Sosyal olaylar matematiksel olarak hiç incelenemez', 'B', 4),
        ('e251b948-acdd-5cb7-970b-88e3a4dc23bb'::uuid, '623c28bb-c9cf-4ae7-8c18-e9400c35e66b'::uuid, 'Sosyal bir sistemde geri besleme döngüsü küçük bir olayı nasıl büyütebilir?', 2, 2, 3, 'Bir olayın sonucu yeni kararları etkiler; bu kararlar da ilk olayı güçlendirir veya zayıflatır ve zincirleme değişim yaratır.', 'Davranışların sonuçları zamanla yeni davranışları tetikleyebilir', 'Sistemin bütün aktörleri aynı anda ortadan kalkabilir', 'Bilgi sistemden tamamen silinerek değişimi durdurabilir', 'Her kararın sonucu önceden sabitlenerek dalgalanma engellenebilir', 'A', 5),
        ('fef78273-68ff-5435-a112-19dbee28d506'::uuid, '623c28bb-c9cf-4ae7-8c18-e9400c35e66b'::uuid, 'Deterministik bir sistemde bile uzun vadeli tahmin neden zorlaşabilir?', 2, 2, 3, 'Kurallar belirli olsa bile başlangıç koşullarındaki küçük ölçüm hataları büyürse uzun vadeli sonuçlar pratikte öngörülemez hale gelebilir.', 'Sistemin hiçbir kuralı bulunmadığı için', 'Başlangıç ölçümündeki küçük belirsizlikler büyüyebildiği için', 'Bütün değişkenlerin birbirinden tamamen ve kesin olarak bağımsız olması', 'Sonuçlar yalnızca gözlemcinin isteğine göre oluştuğu için', 'B', 6),
        ('22b3c068-664e-5c00-9f44-84709e899cb6'::uuid, '623c28bb-c9cf-4ae7-8c18-e9400c35e66b'::uuid, 'Kaotik sosyal sistemlerde hangi politika yaklaşımı daha dayanıklıdır?', 3, 3, 3, 'Uyarlanabilir politika, sonuçları izler ve yeni bilgi geldikçe adımları günceller; bu yaklaşım belirsizlikte daha dayanıklıdır.', 'Tek bir tahmine bağlı kalıp değişmez bir planı her koşulda sürdürmek', 'Geri bildirim almayan merkezi kararlar', 'Sonuçları izleyip gerektiğinde yön değiştiren uyarlanabilir plan', 'Belirsizliği tamamen yok sayan hızlı uygulama', 'C', 7),
        ('a57b8978-fdcb-57cd-8b2a-9aa81f21a1d3'::uuid, '623c28bb-c9cf-4ae7-8c18-e9400c35e66b'::uuid, 'Doğrusal olmayan bir sistemin doğrusal sistemden temel farkı nedir?', 3, 3, 3, 'Doğrusal olmayan sistemlerde girdideki küçük bir değişiklik orantısız bir sonuç yaratabilir; etkiler basitçe toplanmayabilir.', 'Hiçbir girdinin sistem sonucunu hiçbir koşulda ve ölçüde etkilememesi', 'Sadece fiziksel ortamlarda görülmesi', 'Bütün değişkenlerin sabit kalması', 'Girdi ile sonuç arasındaki ilişkinin orantılı olmak zorunda olmaması', 'D', 8),
        ('4c95cce5-4971-578e-afda-a724c11fff37'::uuid, '7bf25405-29a4-4ba1-9f31-f3ad2b0f1a28'::uuid, 'Marka kimliği ile logo arasındaki fark nasıl açıklanır?', 1, 1, 2, 'Logo tanınmayı sağlayan görsel bir işarettir; marka kimliği ise değerleri, dili, kişiliği ve vaat edilen deneyimi kapsar.', 'Logo markanın bütün müşteri deneyimini tek başına oluşturur', 'Marka kimliği yalnızca renk kodlarından oluşur', 'Logo görsel işarettir; kimlik anlam ve vaat bütünüdür', 'Kimlik ve logo her durumda aynı kavramdır', 'C', 4),
        ('81cfb9d3-3bb4-5ed2-80fc-b121519f6e8e'::uuid, '7bf25405-29a4-4ba1-9f31-f3ad2b0f1a28'::uuid, 'Bir marka vaadinin güven üretmesi için hangi koşul gereklidir?', 2, 2, 2, 'Müşterinin yaşadığı ürün, hizmet ve iletişim deneyimi verilen vaatle tutarlı olduğunda güven güçlenir.', 'Vaat yalnızca reklamda görünmelidir', 'Her müşteri için farklı, çelişkili ve öngörülemez bir deneyim sunmalıdır', 'Logo sık sık değiştirilmelidir', 'Temas noktalarındaki gerçek deneyim vaatle tutarlı olmalıdır', 'D', 5),
        ('5d3858fa-a2cb-5c25-92d8-3878293c9f16'::uuid, '7bf25405-29a4-4ba1-9f31-f3ad2b0f1a28'::uuid, 'Kriz iletişimindeki ''altın saat'' yaklaşımı hangi eylemi destekler?', 2, 2, 2, 'İlk açıklama algının çerçevesini etkileyebilir; hızlı, doğrulanmış ve sorumluluk alan iletişim güveni korumaya yardımcı olur.', 'Sorun kamuoyunda kendiliğinden tamamen unutulana kadar sessizce beklemeyi', 'İlk aşamada hızlı ve sorumluluk alan açıklama yapmayı', 'Yalnızca rakipleri suçlayan mesaj yayımlamayı', 'Müşterilerin sorularını yanıtsız bırakmayı', 'B', 6),
        ('1d5361dc-e25e-5185-9865-7c8c2bc9152a'::uuid, '7bf25405-29a4-4ba1-9f31-f3ad2b0f1a28'::uuid, 'Markanın soyut ve duygusal değer üretmesi hangi sonucu doğurabilir?', 2, 2, 2, 'Güven, statü veya aidiyet gibi duygusal anlamlar, benzer işlevli ürünler arasında tercihi ve ödenmeye razı olunan fiyatı etkileyebilir.', 'Ürünün kullanımını ve deneyimini önemsizleştirir', 'Müşterinin bütün tercihlerini rastlantısal hale getirir', 'Benzer ürünler arasında tercih ve fiyat kabulünü etkileyebilir', 'Marka ile müşteri arasındaki güven ilişkisini tamamen ortadan kaldırır', 'C', 7),
        ('1bcc8e79-edad-5b30-baa3-dc6c250ca0f6'::uuid, '7bf25405-29a4-4ba1-9f31-f3ad2b0f1a28'::uuid, 'Marka temas noktalarında tutarlılık neden önemlidir?', 3, 3, 2, 'Tutarlı dil, görsel kimlik ve hizmet deneyimi müşterinin markadan ne bekleyeceğini anlamasını kolaylaştırır ve güven oluşturur.', 'Her temas noktasında birbirinden farklı marka kimliği yaratmak', 'Müşteri beklentilerini sürekli değiştirmek için', 'Sadece logoyu daha büyük göstermek için', 'Tekrarlanan deneyimlerin güvenilir bir anlam oluşturması için', 'D', 8),
        ('40cd4a23-8c6e-5220-9e81-1152fdcae186'::uuid, '804bdec7-75d8-4aed-a7d9-43a7e0b3979b'::uuid, 'İnsan etkisinin jeolojik izlerinden biri olarak metinde hangisi öne çıkar?', 1, 1, 3, 'Plastik, beton ve nükleer denemelerden kalan izotoplar, insan faaliyetlerinin jeolojik kayıtlarda ayırt edilebilir izler bırakmasına örnektir.', 'Yalnızca mevsimsel yağışlar', 'Okyanusların doğal gelgitleri', 'Kıtasal kayaların milyonlarca yıl boyunca doğal aşınması', 'Plastik, beton ve nükleer izotopların birikimi', 'D', 4),
        ('60df4539-b87b-5e5c-a642-b26396eba4a0'::uuid, '804bdec7-75d8-4aed-a7d9-43a7e0b3979b'::uuid, 'Büyük Hızlanma kavramı hangi dönemdeki küresel artışları anlatır?', 1, 1, 3, 'Büyük Hızlanma, yaklaşık 1950 sonrasında insan nüfusu, üretim, enerji kullanımı ve tüketimde görülen keskin artışları ifade eder.', '1950 sonrasında üretim, nüfus ve tüketimdeki hızlı artışları', 'Orta Çağ''da tarımsal üretimin tek ve sınırlı bir bölgede yükselmesini', 'Sanayi öncesinde avcılığın mevsimsel değişimini', 'Gelecekte nüfusun tamamen sabitlenmesini', 'A', 5),
        ('39caa378-4b6b-5509-a387-5b99d57cfb6b'::uuid, '804bdec7-75d8-4aed-a7d9-43a7e0b3979b'::uuid, 'Antroposen''in resmî jeolojik çağ olarak kabulünde neden tartışma vardır?', 2, 2, 3, 'Tartışma, insan etkisinin gerçekliğinden çok, çağın başlangıç tarihinin ve küresel sınırının hangi jeolojik kanıtla tanımlanacağı üzerinedir.', 'İnsan etkisinin Dünya''da hiçbir bölgede ölçülememesi', 'Antroposen için başlangıç tarihinin hangi kanıtla seçileceği', 'İklim değişikliğinin yalnızca tek ve küçük bir şehirde görülmesi', 'Jeolojik çağların bilimsel olarak kullanılmaması', 'B', 6),
        ('d2f49f74-5917-5051-9ca4-976cafa94110'::uuid, '804bdec7-75d8-4aed-a7d9-43a7e0b3979b'::uuid, 'İyi ve kötü Antroposen ayrımı hangi karşıtlığı vurgular?', 3, 3, 3, 'İyi Antroposen, insanın teknolojiyi onarım ve adalet için kullanabileceğini; kötü Antroposen ise tahribatı sürdüren yaklaşımı simgeler.', 'Yalnızca doğa olaylarının insanlardan bağımsız ilerlemesini', 'Bilimsel verilerin bütün ahlaki tartışmaları bütünüyle gereksiz kılmasını', 'İnsan etkisinin onarım veya tahribat yönünde kullanılabilmesini', 'Jeolojik kayıtların insan faaliyetlerini hiç göstermemesini', 'C', 7),
        ('190f1871-5eb7-5054-a32f-e7b21b4d986e'::uuid, '804bdec7-75d8-4aed-a7d9-43a7e0b3979b'::uuid, 'Antroposen koşullarında sorumlu bir politika hangi bileşimi gerektirir?', 3, 3, 3, 'İnsan etkisinin ölçeği, ekolojik onarımın bilimsel verilerle ve toplumsal adalet gözeten yönetişimle birlikte yürütülmesini gerektirir.', 'Yalnızca ekonomik büyümeyi hızlandırmayı', 'Bilimsel verileri karar süreçlerinden çıkarmayı', 'Çevre sorunlarını yalnızca bireysel tercihlerle çözmeye çalışma yaklaşımını', 'Ekolojik onarımda bilim, yönetişim ve adaleti birlikte gözetmeyi', 'D', 8),
        ('7a7deb5c-c641-5983-832f-5642f18b25e1'::uuid, '8b03aea9-c5c6-4a56-9cf7-a19059db14aa'::uuid, 'Çerçeveleme etkisi algı yönetiminde neyi gösterir?', 1, 1, 2, 'Çerçeveleme, içerik aynı kalsa bile bilginin hangi bağlamda ve hangi kelimelerle sunulduğunun değerlendirmeyi etkileyebilmesidir.', 'Bir mesajın yalnızca görsellerle aktarılabilmesini', 'Gerçeklerin hiçbir koşulda yorumlanamayacağını', 'Bütün insanların aynı mesajı aynı anlamda ve koşulda algılamasını her zaman', 'Aynı bilginin sunuluş biçiminin değerlendirmeyi değiştirebilmesini', 'D', 4),
        ('4cc4ffeb-a6d3-5712-9742-12fe14d7f0c3'::uuid, '8b03aea9-c5c6-4a56-9cf7-a19059db14aa'::uuid, 'Doğrulama yanlılığı kişinin bilgiyi nasıl seçmesine yol açar?', 2, 2, 2, 'Doğrulama yanlılığında kişi, önceden benimsediği görüşle uyumlu bilgiyi aramaya ve çelişen kanıtı küçümsemeye daha yatkındır.', 'Önceden benimsediği görüşü destekleyen kanıtları daha kolay kabul etmesine', 'Kendi inancıyla çelişen kanıtları eşit, tarafsız ve dikkatle incelemesini her zaman', 'Kaynakların güvenilirliğini her zaman tamamen reddetmesine', 'Her görüşü aynı anda doğru saymasına', 'A', 5),
        ('16d813aa-41ef-5d1a-8a42-8ddbddc8559f'::uuid, '8b03aea9-c5c6-4a56-9cf7-a19059db14aa'::uuid, 'Bir deepfake iddiasını kontrol etmek için en uygun ilk adım hangisidir?', 1, 1, 2, 'Kaynağı, tarihi ve bağımsız doğrulamaları kontrol etmek; görüntünün tek başına sunduğu izlenimden daha güvenilir bir değerlendirme sağlar.', 'Videoyu yalnızca paylaşım sayısına göre doğru kabul etmek', 'Güvenilir ve bağımsız kaynaklarda olayın izini sürmek', 'İçeriği kesip biçerek kaynağını gizlemek', 'Duygusal tepkiyi kanıt yerine kullanmak', 'B', 6),
        ('e5b5e6ca-f9a1-5567-a916-5e3cfcb7e058'::uuid, '8b03aea9-c5c6-4a56-9cf7-a19059db14aa'::uuid, 'Algı yönetimi hangi araçları birlikte kullanarak etkisini artırabilir?', 2, 2, 2, 'Tekrarlanan mesajlar, güçlü duygular ve seçilmiş bağlam birlikte kullanıldığında kişinin dikkatini ve olay yorumunu yönlendirebilir.', 'Yalnızca teknik terimleri çoğaltarak', 'Mesajı bütün bağlamından koparmadan', 'Tekrarlama, duygusal çağrışım ve seçilmiş bağlamı birleştirerek', 'Tekrarlama, duygu ve seçilmiş bağlamı birlikte etkili biçimde kullanarak', 'C', 7),
        ('36fe5c1f-d90f-5a00-9311-ead8a1bab971'::uuid, '8b03aea9-c5c6-4a56-9cf7-a19059db14aa'::uuid, 'Eleştirel medya okuryazarlığı için en sağlam yaklaşım nedir?', 3, 3, 2, 'Eleştirel okuryazarlık, kaynağı ve kanıtı incelemeyi; mesajın amacını ve olası alternatif açıklamaları karşılaştırmayı gerektirir.', 'Görüntü varsa yazılı açıklamayı gereksiz görmek', 'En çok paylaşılan iddiayı otomatik olarak doğru saymak', 'Yalnızca kendi görüşünü destekleyen hesapları ve kanıtları sürekli izlemek', 'Kaynağı, kanıtı, amacı ve alternatif açıklamaları birlikte sorgulamak', 'D', 8),
        ('c6c004d8-e663-58f5-9851-3edf169f65e7'::uuid, '9213a128-3898-4e7a-a810-47d6f19f964c'::uuid, 'Merkez bankasının açık piyasa alımı yapması genellikle hangi etkiyi amaçlar?', 1, 1, 2, 'Merkez bankası menkul kıymet aldığında sisteme likidite sağlayarak faizleri ve kredi koşullarını gevşetmeyi amaçlayabilir.', 'Dolaşımdaki parayı azaltıp faizi yükseltmeyi', 'Kamu bütçesini doğrudan özel şirketlere aktarmayı', 'Kredi talebini tamamen ortadan kaldırmayı', 'Likiditeyi artırıp finansal koşulları gevşetmeyi', 'D', 4),
        ('d3f7d3ee-46e5-59b0-912a-69c9f4b7e0eb'::uuid, '9213a128-3898-4e7a-a810-47d6f19f964c'::uuid, 'Zorunlu karşılık oranının artırılması bankacılık sisteminde neye yol açabilir?', 2, 2, 2, 'Bankalar daha büyük bir payı merkez bankasında tutmak zorunda kaldığında krediye dönüştürebilecekleri kaynak ve sistem likiditesi azalabilir.', 'Kredi yaratma kapasitesinin ve likiditenin azalmasına', 'Para politikasının etkisizleşmesine', 'Bankaların sınırsız kredi vermesine', 'Enflasyon beklentilerinin otomatik olarak yok olmasına', 'A', 5),
        ('7b1c0aa0-bc4e-51d4-a2b1-0e22c2ca279a'::uuid, '9213a128-3898-4e7a-a810-47d6f19f964c'::uuid, 'Enflasyon beklentileri para politikasında neden önemlidir?', 2, 2, 2, 'Beklentiler yükselirse ücret, fiyat ve harcama kararları gelecekteki enflasyonu besleyebilir; bu yüzden merkez bankaları beklentileri yönetmeye çalışır.', 'Fiyatların geçmişte hiç değişmediğini gösterdiği için', 'Ücret, fiyat ve harcama kararlarını etkilemesi', 'Yalnızca borsa fiyatlarını belirlediği için', 'Faiz kararlarını bütün ülkelerde aynı yaptığı için', 'B', 6),
        ('b82ac7af-3119-5f2a-98b5-fde29fd45847'::uuid, '9213a128-3898-4e7a-a810-47d6f19f964c'::uuid, 'Merkez bankası bağımsızlığının temel amacı nasıl ifade edilir?', 3, 3, 2, 'Bağımsızlık, kararların günlük siyasi baskıdan uzak ve fiyat istikrarı gibi açık görevler doğrultusunda alınmasına katkı sağlar; hesap verebilirlik yine sürer.', 'Ekonomik hedefleri yalnızca tek bir şirketin belirlemesini', 'Para politikasını yasama ve demokratik denetim mekanizmalarından tamamen koparmayı', 'Kararların kısa vadeli siyasi baskılardan daha az etkilenmesini sağlamak', 'Faiz kararlarını piyasa verilerinden bağımsızlaştırmayı', 'C', 7),
        ('18d61d3a-92fe-56ab-8b45-85ec5ff6eded'::uuid, '9213a128-3898-4e7a-a810-47d6f19f964c'::uuid, 'Ekonomik durgunlukta politika faizinin düşürülmesi hangi sonucu hedefler?', 2, 2, 2, 'Faiz indirimi, borçlanma maliyetini düşürerek tüketim ve yatırım talebini desteklemeyi hedefleyebilir; etkisi ekonomik koşullara bağlıdır.', 'Borçlanma maliyetini artırıp toplam talebi iyice bastırmayı', 'Merkez bankasının bütün riskleri üstlenmesini', 'İhracat vergilerini otomatik olarak artırmayı', 'Kredi koşullarını gevşetip harcama ve yatırımı desteklemeyi', 'D', 8),
        ('42318e38-bcd3-5459-9b90-459fe5407e0c'::uuid, '9ee5d169-5e73-48da-a933-bb146ca1985f'::uuid, 'Sanat terapisinde süreç ile ürün arasındaki öncelik nasıl açıklanır?', 1, 1, 2, 'Sanat terapisinde amaç sergilenebilir bir eser üretmek değil, üretim sürecinin duygu, farkındalık ve ilişki kurmayı desteklemesidir.', 'Ortaya çıkan nesnenin estetik değerini her zaman tek ve birincil ölçüt saymayı', 'Yalnızca profesyonel teknik başarı ölçülür', 'Üretim süreci ve kişinin deneyimi, ürünün görünüşünden daha önemlidir', 'Terapist eseri danışan adına tamamlar', 'C', 4),
        ('b4644291-6440-52c7-8534-06a8766436db'::uuid, '9ee5d169-5e73-48da-a933-bb146ca1985f'::uuid, 'Sanat terapistinin temel rolü aşağıdakilerden hangisidir?', 2, 2, 2, 'Terapist güvenli bir alan sağlar, süreci yapılandırır ve danışanın anlamlandırmasını kendi yorumuyla bastırmadan destekler.', 'Danışanın eserine tek, değişmez ve tartışmasız bir doğru anlam vermeyi', 'Sanatsal yeteneği puanlayarak tedavi kararı almak', 'Her duyguyu çizimle ifade etmeyi zorunlu kılmak', 'Güvenli ortam kurup süreci etik ve klinik açıdan rehberlemek', 'D', 5),
        ('4ae65637-5a83-50a4-8a6a-e4df979d53d1'::uuid, '9ee5d169-5e73-48da-a933-bb146ca1985f'::uuid, 'Sanat terapisine katılım için neden profesyonel sanat becerisi gerekmez?', 1, 1, 2, 'Sanat terapisi, teknik yarışma değildir; çizim, renk veya hareket aracılığıyla kişinin deneyimine erişmesini ve onu ifade etmesini amaçlar.', 'Çalışmanın hedefi estetik performans değil, ifade ve farkındalıktır', 'Terapistin bütün yaratıcı çalışmayı danışan yerine kendisinin yapması', 'Sanat eserleri hiçbir zaman değerlendirilmediği için', 'Yaratıcılık yalnızca çocuklarda bulunduğu için', 'A', 6),
        ('91e7a145-5e01-5638-bfc3-1132abd9dbbe'::uuid, '9ee5d169-5e73-48da-a933-bb146ca1985f'::uuid, 'Travma çalışmasında sanatsal ifade hangi yararı sağlayabilir?', 2, 2, 2, 'Sembolik ve kontrollü üretim, kişinin söze dökmekte zorlandığı deneyimleri güvenli sınırlar içinde ele almasına yardımcı olabilir; tedavi garanti etmez.', 'Yaşanan olayı ayrıntılı biçimde yeniden yaşamayı kişi için zorunlu tutabilir', 'Terapistin danışan adına bütün kararları almasını sağlar', 'Söze dökülmesi zor deneyimler için güvenli bir ifade kanalı açabilir', 'Travmanın etkisini tek seansta tamamen ortadan kaldırır', 'C', 7),
        ('8ff9faf2-368f-5eaf-8479-91c6076959a7'::uuid, '9ee5d169-5e73-48da-a933-bb146ca1985f'::uuid, 'Sanat terapisinde hangi uygulama grubu metindeki yaklaşımı yansıtır?', 1, 1, 2, 'Sanat terapisi, kişinin ihtiyacına göre resim, kolaj, müzik, hareket veya heykel gibi farklı yaratıcı araçlardan yararlanabilir.', 'Yalnızca yazılı sınav ve ezber çalışması', 'Yalnızca tek bir resim tekniği ve değişmez bir yönerge kullanmak', 'Danışanın yerine terapistin hazırladığı hazır çizimler', 'Kolaj, resim, müzik veya heykel gibi farklı yaratıcı araçlar', 'D', 8),
        ('85d56b18-38b1-5836-a587-609ddb2a6a40'::uuid, 'c4650166-8717-419f-82be-ee6f571c4335'::uuid, 'Minimalizm hakkında metnin düzelttiği yaygın yanlış anlama nedir?', 1, 1, 2, 'Minimalizm her şeyi bırakmak değil, sahip olunan ve yapılan şeyleri kişinin temel değerleriyle uyumlu biçimde seçmektir.', 'Önemli seçimleri kişinin temel değerleriyle ilişkilendirmek', 'Gereksiz tüketimi sorgulamak', 'Dikkati anlamlı etkinliklere ayırmak', 'Bütün eşyaları ayrım yapmadan terk etmek', 'D', 4),
        ('5add4206-b35a-5d2c-9181-0c6c11104178'::uuid, 'c4650166-8717-419f-82be-ee6f571c4335'::uuid, 'Ödül yerine anlam ve gelişim sağlayan bir etkinlik hangi mutluluk yaklaşımına yakındır?', 2, 2, 2, 'Eudaimonik yaklaşım, anlam, amaç ve gelişimi; yalnızca anlık haz sağlayan hedonik tercihlerin ötesinde değerlendirir.', 'Eudaimonik ve anlam odaklı mutluluğa', 'Anlık haz odaklı mutluluğa', 'Rastlantısal tüketime', 'Anlık haz odaklı kısa süreli mutluluğa', 'A', 5),
        ('8c496de8-934a-579c-9f09-62a7f958ef94'::uuid, 'c4650166-8717-419f-82be-ee6f571c4335'::uuid, 'Bir eşyayı azaltma kararında minimalizme uygun soru hangisidir?', 2, 2, 2, 'Değer ve güncel ihtiyaç sorusu, eşyayı yalnızca fiyatına veya başkalarının tercihine göre değil, kişinin yaşam amacına göre değerlendirmesine yardım eder.', 'Bu eşya en pahalı olan mı?', 'Bu eşya değerlerime ve güncel ihtiyacıma gerçekten hizmet ediyor mu?', 'Bu eşya başkalarında da var mı?', 'Bu eşyayı saklamak için daha büyük ve pahalı bir ev satın alabilir miyim?', 'B', 6),
        ('c6ee32e8-b1e2-55ff-9055-d1d5bea657f3'::uuid, 'c4650166-8717-419f-82be-ee6f571c4335'::uuid, 'Tüketim fazlasının dikkat üzerindeki etkisi nasıl açıklanır?', 2, 2, 2, 'Fazla eşya, düzenleme ve karar verme için daha çok dikkat gerektirebilir; bu da kişinin önemli işlere ayırdığı zihinsel alanı daraltabilir.', 'Seçenekler arttıkça karar vermek her zaman ve kesinlikle kolaylaşır', 'Eşya sayısı arttıkça zihinsel yük kesinlikle azalır', 'Fazla eşya ve seçenek, bakım ve karar yükünü artırabilir', 'Tüketim davranışı dikkatle hiçbir ilişki taşımaz', 'C', 7),
        ('99d1a596-cec8-5da0-8721-0cfa2f3982e6'::uuid, 'c4650166-8717-419f-82be-ee6f571c4335'::uuid, 'Minimalizmin çevresel katkısı hangi mekanizmayla ortaya çıkabilir?', 3, 3, 2, 'Daha az ve daha bilinçli tüketim, üretim için gereken kaynakları ve kullanım sonrası atığı azaltma potansiyeli taşır.', 'Her ürünü daha hızlı yenileyerek', 'Tüketim miktarını artırıp depolama alanını sürekli olarak büyütmek', 'İhtiyaç dışı ürünleri sürekli değiştirerek', 'Gereksiz tüketimi ve buna bağlı kaynak-atık akışını azaltarak', 'D', 8),
        ('10641079-ea8b-5244-af24-7cc58d12776e'::uuid, 'd580e67a-90f8-457e-8582-11aca491c632'::uuid, 'Chalmers''ın ''zor problem'' ifadesi hangi soruya odaklanır?', 1, 1, 3, 'Zor problem, sinirsel ve fiziksel süreçlerin nasıl olup da kırmızıyı görmek gibi öznel bir deneyime dönüştüğünü sorar.', 'Davranışların neden dışarıdan gözlenebilir hale gelemediğine', 'Beynin hangi bölgesinin en büyük olduğuna', 'Bir bilgisayarın ne kadar hızlı hesap yaptığına', 'Fiziksel süreçlerin neden öznel bir deneyim ürettiğine', 'D', 4),
        ('827eb19c-8350-5014-9a3f-88fac68bd55d'::uuid, 'd580e67a-90f8-457e-8582-11aca491c632'::uuid, 'Felsefi zombi düşünce deneyi hangi ayrımı görünür kılar?', 2, 2, 3, 'Felsefi zombi, bilinçliymiş gibi davranan fakat içsel deneyimi olmayan bir varlığın mantıksal olarak düşünülebileceğini tartışır.', 'Dışarıdan aynı davranışı gösterme ile içsel deneyim sahibi olma arasındaki farkı', 'Beden ile çevre arasındaki temel, ölçülebilir ve biyolojik farkı açıklama biçimini bütünüyle', 'Zekâ ile hafıza arasındaki biyolojik farkı', 'Duygu ile dil arasındaki kültürel farkı', 'A', 5),
        ('640d89eb-0495-5950-a4f1-cc226c2f0a20'::uuid, 'd580e67a-90f8-457e-8582-11aca491c632'::uuid, 'Turing testinin bilinç tartışmasındaki temel sınırlılığı nedir?', 2, 2, 3, 'Turing testi konuşma davranışını ölçer; bir sistemin ikna edici yanıt vermesi, gerçekten öznel deneyim yaşadığını kesin olarak göstermez.', 'Dilsel davranışı hiç ölçememesi', 'Başarılı davranışı içsel öznel deneyimin kesin kanıtı sayamaması', 'İnsanların makineyle doğal ve anlamlı iletişim kurmasını engellemesi', 'Yalnızca biyolojik beyinleri test etmesi', 'B', 6),
        ('af493edb-c5e9-5373-a74a-3cb58e94e035'::uuid, 'd580e67a-90f8-457e-8582-11aca491c632'::uuid, 'Yapay zekâda insan benzeri davranış gözlendiğinde hangi soru açık kalır?', 3, 3, 3, 'Davranışsal başarı ile bilinçli deneyim aynı şey değildir; yapay sistemlerin gerçekten deneyim yaşayıp yaşamadığı çözümlenmemiştir.', 'Sistemin veri işleyip işlemediği', 'Sistemin hiçbir algoritma kullanmadığı', 'Bu davranışın ardında gerçek bir öznel deneyim bulunup bulunmadığı', 'Sistemin insan dilini her bağlamda uygun biçimde tanıyıp tanımadığı', 'C', 7),
        ('cefc619a-ea8b-57f0-9010-e6590f5cbc00'::uuid, 'd580e67a-90f8-457e-8582-11aca491c632'::uuid, 'Qualia kavramı bilinç tartışmasına hangi bakış açısını ekler?', 1, 1, 3, 'Qualia, acı, renk veya tat gibi deneyimlerin birinci kişi açısından nasıl hissettirdiğini ifade eder.', 'Bir makinenin fiziksel ağırlığını', 'Yalnızca dışarıdan ölçülebilen bedensel otomatik refleksleri', 'Bir algoritmanın işlem süresini', 'Deneyimin kişinin kendi açısından nasıl hissedildiğini', 'D', 8),
        ('b40c7b3b-db86-51eb-be38-332e8bb7f313'::uuid, 'de4d10fc-7217-46be-8216-b63f6bcc680d'::uuid, 'Bir MVP''nin girişim için temel amacı nedir?', 1, 1, 2, 'Minimum uygulanabilir ürün, temel varsayımları gerçek kullanıcılarla test etmek ve geri bildirimle öğrenmek için kullanılır.', 'Ürünü bütün temel özellikleriyle ilk günden eksiksiz ve kusursuz tamamlamak', 'Pazarlama bütçesini ürün geliştirmeden önce tüketmek', 'Yatırımcıya yalnızca yüksek değerleme göstermek', 'Varsayımları sınırlı kaynakla test edip kullanıcı öğrenmesi sağlamak', 'D', 4),
        ('797ade74-138f-5aac-b7f1-a463fb4b6696'::uuid, 'de4d10fc-7217-46be-8216-b63f6bcc680d'::uuid, 'Ürün-pazar uyumu hangi durumu ifade eder?', 2, 2, 2, 'Ürün-pazar uyumu, belirli kullanıcıların ürünü tekrar tekrar kullanması ve onun önemli bir ihtiyacı karşıladığını göstermesidir.', 'Belirli bir kullanıcı grubunun ürünü düzenli kullanıp değerli bulmasını', 'Yatırımcının fikri ilginç bulmasını', 'Kurucunun ürünü kişisel olarak çok beğenip herkese ısrarla ve sürekli önermesi', 'Ürünün rakiplerinin hiç olmamasını', 'A', 5),
        ('74b28116-9288-5ff7-8d8c-125db8ff2e55'::uuid, 'de4d10fc-7217-46be-8216-b63f6bcc680d'::uuid, 'Girişim sermayesi almanın temel karşılığı hangi seçenekte doğru verilmiştir?', 2, 2, 2, 'Girişim sermayesi hızlı büyümeyi finanse edebilir; karşılığında kurucu ortaklık payı ve bazı yönetişim haklarını paylaşır.', 'Kurucunun hiçbir karar sorumluluğu taşımaması', 'Büyüme kaynağı karşılığında ortaklık ve yönetişim paylaşımı', 'Pazar riskinin yatırımcı tarafından tamamen ve kalıcı biçimde yok edilmesi', 'Geri ödeme gerektirmeyen ve koşulsuz para', 'B', 6),
        ('6dd5cc1b-9ef9-5322-8cf7-4100a2bf0109'::uuid, 'de4d10fc-7217-46be-8216-b63f6bcc680d'::uuid, 'Girişimin pivot etmesi ne anlama gelir?', 3, 3, 2, 'Pivot, kullanıcı geri bildirimi veya pazar verisi ilk varsayımları doğrulamadığında stratejik yönü öğrenmeye göre değiştirmektir.', 'Yalnızca logoyu ve şirket adını değiştirmek', 'Daima ilk fikre bağlı kalıp öğrenilen veriye göre değişimi sürekli reddetmek', 'Öğrenilen veriye göre ürün, müşteri veya iş modelinde yön değiştirmek', 'Ürünü test etmeden bütün pazarlara açılmak', 'C', 7),
        ('34ce91c4-b3f3-5260-88f1-ec722d8d1610'::uuid, 'de4d10fc-7217-46be-8216-b63f6bcc680d'::uuid, 'Ağ etkisi güçlü bir dijital üründe değer nasıl artabilir?', 2, 2, 2, 'Ağ etkisinde daha çok kullanıcı, diğer kullanıcıların ulaşabileceği bağlantıları veya içerikleri artırarak ürünün toplam faydasını büyütebilir.', 'Kullanıcı sayısı arttıkça her kişi için faydanın zamanla ve sürekli azalmasıyla', 'Büyüme arttıkça bütün işletme maliyetleri sıfırlandığı için', 'Ürün yalnızca tek bir kişiye hizmet verdiği için', 'Kullanıcı sayısı arttıkça bağlantılar ve kullanım değeri çoğalabildiği için', 'D', 8),
        ('b06706ca-4a4f-502d-ab54-7113f01ae650'::uuid, 'df87d7e9-8141-40c8-84a6-0e1778c68aa2'::uuid, 'Ticaret savaşında gümrük tarifelerinin doğrudan sonuçlarından biri nedir?', 1, 1, 2, 'Tarife ithal ürünün maliyetini yükseltebilir; karşı ülke de misilleme yaparsa ticaret hacmi ve fiyatlar etkilenebilir.', 'İthal ürünlerin fiyatını ve karşı ülkenin misilleme riskini artırması', 'Misilleme ihtimalinin tamamen ortadan kalkması', 'İthal ürünlerin her pazarda ve her koşulda sürekli olarak ve hızla ucuzlaması', 'Tedarik zincirlerinin hiçbir değişiklik yaşamaması', 'A', 4),
        ('1c815d9a-5cc3-5461-851a-c80f6b6dd1c2'::uuid, 'df87d7e9-8141-40c8-84a6-0e1778c68aa2'::uuid, 'Mutlak ve göreli kazanç ayrımı ticaret politikasında hangi farkı anlatır?', 3, 3, 2, 'Mutlak kazanç toplam refah veya üretimdeki artışı, göreli kazanç ise bir tarafın diğerine kıyasla avantajını ayrı ayrı değerlendirmeyi sağlar.', 'Mutlak kazanç yalnızca para birimini, göreli kazanç ise yalnızca vergiyi ve fiyatları ölçer', 'Bir tarafın toplam kazanımı ile diğerine göre konumunun ayrı değerlendirilebilmesini', 'Mutlak kazanç kısa vadeyi, göreli kazanç uzun vadeyi zorunlu olarak gösterir', 'Mutlak kazanç üretimi; göreli kazanç tüketimi hiçbir zaman dikkate almaz', 'B', 5),
        ('a5a9742a-752d-54f3-8041-ea732d9b9e42'::uuid, 'df87d7e9-8141-40c8-84a6-0e1778c68aa2'::uuid, 'Friend-shoring yaklaşımının temel ödünleşimi nedir?', 2, 2, 2, 'Dost veya güvenilir ülkelerle tedarik kurmak şoklara dayanıklılığı artırabilir; ancak daha pahalı veya daha az çeşitlendirilmiş olabilir.', 'Siyasi ilişkileri ticari kararlardan tamamen ayırması', 'Tedarik zincirlerini bütün ülkelerden bağımsız ve tamamen güvenli hale getirmesi', 'Tedarik güvenliğini artırırken maliyeti veya seçenekleri azaltabilmesi', 'Her ürünü en düşük maliyetli ülkeden alma zorunluluğu', 'C', 6),
        ('1b79be66-d8a0-5efc-95f7-0b449ba89b70'::uuid, 'df87d7e9-8141-40c8-84a6-0e1778c68aa2'::uuid, 'Tarifelerin ekonomik yükünü çoğunlukla kimler taşır?', 2, 2, 2, 'Tarifeler ithalat maliyetini artırır; bu yük daha yüksek fiyat, düşük kâr veya daha düşük talep yoluyla işletme ve tüketicilere dağılabilir.', 'Yalnızca tarife koyan hükümet', 'Yalnızca merkez bankası', 'Yalnızca yabancı üreticiler ve hiçbir yerli ekonomik aktör değil', 'İthalatçı, işletme ve tüketiciler arasında farklı biçimlerde', 'D', 7),
        ('8b6f336a-eab4-5ac7-803d-1b00a28aceb8'::uuid, 'df87d7e9-8141-40c8-84a6-0e1778c68aa2'::uuid, 'Ticaret savaşlarının ''kazananı'' için metnin dengeli sonucu hangisidir?', 3, 3, 2, 'Ticaret savaşı tarafların pazarlık gücünü artırabilir, ancak misilleme ve verim kaybı nedeniyle toplam refah çoğu zaman düşer.', 'Tarafların daha az kaybetmeye çalışması ve net refah kaybı', 'Tarife uygulayan tarafın her durumda refah kazanması', 'Her iki tarafın da bütün ekonomik kayıpları tamamen telafi etmesi', 'Tedarik zincirlerinin çatışmadan her zaman güçlenerek çıkması', 'A', 8),
        ('4f3e0cbe-96dc-57b2-8093-df3a82e8c731'::uuid, 'f5b607f5-c508-493f-aa91-a2b8941e18ec'::uuid, 'Kahramanın yolculuğunda ''maceraya çağrı'' aşaması neyi başlatır?', 1, 1, 2, 'Maceraya çağrı, kahramanı alışılmış düzeninden çıkaran ve dönüşüm gerektiren olay veya davettir.', 'Kahramanın değişimi reddedip eski düzenine kesin olarak dönmesini', 'Hikâyenin bütün çatışmalarının sona ermesini', 'Kahramanın ödülü baştan elde etmesini', 'Kahramanı alışılmış dünyasının dışına çıkaracak ilk daveti', 'D', 4),
        ('ad8b83df-e34c-5943-a85b-c9ad3a9d0502'::uuid, 'f5b607f5-c508-493f-aa91-a2b8941e18ec'::uuid, 'Eşik bekçisi ve sınavlar kahramanın yolculuğunda hangi işleve sahiptir?', 2, 2, 2, 'Eşik ve sınavlar, kahramanın bilinmeyen dünyaya geçmek için korku ve engellerle yüzleşmesini sağlar.', 'Kahramanın değişim için hazırlığını ve kararlılığını sınamak', 'Kahramanın bütün sorumluluklardan ve sınavlardan kaçmasını sağlamak', 'Hikâyenin sonunda ödülü açıklamak', 'Kahramanın geçmişini tamamen silmek', 'A', 5),
        ('07c1699f-2b62-55e8-9a7b-c4e10d95dd14'::uuid, 'f5b607f5-c508-493f-aa91-a2b8941e18ec'::uuid, 'Gölge arketipi mitolojik anlatılarda çoğunlukla neyi temsil eder?', 2, 2, 2, 'Gölge, kahramanın veya toplumun kabul etmekte zorlandığı korku, arzu ve çatışmalı yönlerin simgesel karşılığı olabilir.', 'Kahramanın dış görünüşünü ve toplum içindeki sosyal statüsünü belirlemek', 'Kişinin bastırdığı korku, çatışma veya kabul etmekte zorlandığı yönleri', 'Toplumun yalnızca hukuki kurallarını', 'Hikâyedeki bütün komik karakterleri', 'B', 6),
        ('7a0f7d73-9ce2-5116-9fc4-8aeff5ca6899'::uuid, 'f5b607f5-c508-493f-aa91-a2b8941e18ec'::uuid, 'Modern süper kahraman anlatıları kahramanın yolculuğundan nasıl yararlanır?', 3, 3, 2, 'Süper kahraman anlatıları, güncel teknolojik veya toplumsal çatışmaları tanıdık dönüşüm aşamaları ve arketiplerle anlatabilir.', 'Kahramanı hiçbir zorlu sınav yaşamadan doğrudan başarılı figüre hızla dönüştürerek', 'Mitolojik sembolleri bütün anlamlarından kopararak', 'Çağdaş çatışmaları çağrı, sınav, dönüşüm ve dönüş aşamalarıyla yapılandırarak', 'Hikâyeyi yalnızca tarihî tanrılarla sınırlayarak', 'C', 7),
        ('dce96eb4-8f04-5821-ae5e-f02e7610771c'::uuid, 'f5b607f5-c508-493f-aa91-a2b8941e18ec'::uuid, 'Mitlerin günümüzde incelenmesinin temel katkısı nedir?', 3, 3, 2, 'Mitolojik analiz, farklı kültürlerde tekrarlanan sembol ve dönüşüm biçimlerini izleyerek ortak insan deneyimleriyle kültürel değerler arasındaki ilişkiyi görünür kılar.', 'Tarihsel olayların bütün ayrıntılarını bilimsel yöntemle kesin, eksiksiz ve tarafsız kanıtlamak', 'Farklı kültürleri tek bir kalıba zorlamak', 'Bireysel deneyimi toplumsal değerlerden ayırmak', 'İnsanların ortak kaygılarını, değerlerini ve dönüşüm biçimlerini anlamaya yardım etmek', 'D', 8);

DO $$
BEGIN
    IF to_regclass('public."ReadingQuestions"') IS NOT NULL THEN
        INSERT INTO public."ReadingQuestions"
            ("Id", "ReadingTextId", "QuestionText", "Type", "BloomLevel", "DifficultyLevel",
             "Explanation", "OptionA", "OptionB", "OptionC", "OptionD", "CorrectAnswer",
             "OrderIndex", "CreatedAt", "CreatedBy", "IsDeleted")
        SELECT id, reading_text_id, question_text, type, bloom_level, difficulty_level,
               explanation, option_a, option_b, option_c, option_d, correct_answer,
               order_index, CURRENT_TIMESTAMP, '00000000-0000-0000-0000-000000000001'::uuid, FALSE
        FROM reading_question_supplement source
        WHERE NOT EXISTS (
            SELECT 1 FROM public."ReadingQuestions" target WHERE target."Id" = source.id
        );
    END IF;

    IF to_regclass('speed_reading.reading_questions') IS NOT NULL THEN
        INSERT INTO speed_reading.reading_questions
            (id, reading_text_id, question_text, type, bloom_level, difficulty_level,
             explanation, option_a, option_b, option_c, option_d, correct_answer,
             order_index, created_at, created_by, is_deleted)
        SELECT id, reading_text_id, question_text, type, bloom_level, difficulty_level,
               explanation, option_a, option_b, option_c, option_d, correct_answer,
               order_index, CURRENT_TIMESTAMP, 'content-supplement-20260915', FALSE
        FROM reading_question_supplement source
        WHERE NOT EXISTS (
            SELECT 1 FROM speed_reading.reading_questions target WHERE target.id = source.id
        );
    END IF;

    IF to_regclass('public."ReadingQuestions"') IS NULL
       AND to_regclass('speed_reading.reading_questions') IS NULL THEN
        RAISE EXCEPTION 'Neither supported reading question table exists';
    END IF;
END $$;

COMMIT;
